    await queryRunner.query("INSERT INTO public.games (id, created_at, updated_at, deleted_at, slug, title, short_description, description, cover_image_url, hero_image_url, sort_order, active, metadata, required_plan_id) VALUES (1, '2026-05-22 10:23:28.081313', '2026-05-22 10:23:28.081313', NULL, 'vice-bay', 'Vice Bay', 'Crime action in a neon metropolis: money, speed, and power at any cost.', 'A crime action game set in the open world of a sunny metropolis. Luxury, neon, and big money conceal cartel wars, boat and helicopter chases, street brawls, and the hero''s journey to the top of a criminal empire.', 'https://res.cloudinary.com/dxrtmaenj/image/upload/q_auto/f_auto/v1779288129/vice-bay_exnofj.png', NULL, 30, true, NULL, 3);");
    await queryRunner.query("INSERT INTO public.games (id, created_at, updated_at, deleted_at, slug, title, short_description, description, cover_image_url, hero_image_url, sort_order, active, metadata, required_plan_id) VALUES (2, '2026-05-22 10:25:45.337701', '2026-05-22 10:25:45.337701', NULL, 'echoes-of-the-fallen', 'Echoes Of The Fallen', 'A brutal survival journey through a flooded, overgrown city after the fall of civilization.', 'Story-driven survival action game set in a drowned, overgrown metropolis. Navigate ruined skyscrapers, scavenge scarce resources, and face hostile factions while uncovering the truth behind civilization’s collapse.', 'https://res.cloudinary.com/dxrtmaenj/image/upload/q_auto/f_auto/v1779288302/echoes-of-fallen_fwxnyu.png', NULL, 30, true, NULL, 3);");
    await queryRunner.query("INSERT INTO public.games (id, created_at, updated_at, deleted_at, slug, title, short_description, description, cover_image_url, hero_image_url, sort_order, active, metadata, required_plan_id) VALUES (3, '2026-05-22 10:27:45.286068', '2026-05-22 10:27:45.286068', NULL, 'cafe-simulator', 'Сafe Simulator', 'Build and manage your dream café, serve great coffee, and create the perfect cozy vibe.', 'Cozy management game where you build, customize, and run your dream coffee shop. Craft specialty drinks, design the perfect interior, hire staff, and turn a small corner café into a thriving neighborhood hotspot.', 'https://res.cloudinary.com/dxrtmaenj/image/upload/q_auto/f_auto/v1779288390/cafe-simulator_lfq14i.png', NULL, 10, true, NULL, 1);");
    await queryRunner.query("INSERT INTO public.games (id, created_at, updated_at, deleted_at, slug, title, short_description, description, cover_image_url, hero_image_url, sort_order, active, metadata, required_plan_id) VALUES (4, '2026-05-22 10:29:17.513798', '2026-05-22 10:29:17.513798', NULL, 'eclipse-horizons', 'Eclipse Horizons', 'An open-world fantasy RPG of magic, floating kingdoms, and destiny beyond the horizon.', 'Open-world fantasy RPG where you explore floating kingdoms, ancient ruins, and living elemental realms. Master arcane powers, form bonds with companions, and uncover secrets that shape the fate of a fractured skybound world.', 'https://res.cloudinary.com/dxrtmaenj/image/upload/q_auto/f_auto/v1779360704/eclipse-horizons_vhvgpg.png', NULL, 10, true, NULL, 1);");
    await queryRunner.query("INSERT INTO public.games (id, created_at, updated_at, deleted_at, slug, title, short_description, description, cover_image_url, hero_image_url, sort_order, active, metadata, required_plan_id) VALUES (5, '2026-05-22 10:31:00.397548', '2026-05-22 10:31:00.397548', NULL, 'starfall-circuit', 'Starfall Circuit', 'Zero‑G space racing with customizable ships and intense galactic circuits.', 'High-speed zero-gravity racing game set across orbital megastructures and deep-space arenas. Pilot customizable anti-grav ships, master tight loops and warp boosts, and compete in a galactic championship where precision and reflexes rule', 'https://res.cloudinary.com/dxrtmaenj/image/upload/q_auto/f_auto/v1779288491/starfall-circuit_zbe1dr.png', NULL, 10, true, NULL, 1);");
    await queryRunner.query("INSERT INTO public.games (id, created_at, updated_at, deleted_at, slug, title, short_description, description, cover_image_url, hero_image_url, sort_order, active, metadata, required_plan_id) VALUES (6, '2026-05-22 10:32:41.630676', '2026-05-22 10:32:41.630676', NULL, 'windward-legacy', 'Windward Legacy', 'An open-world pirate adventure of treasure, naval battles, and legendary seas.', 'Open-world pirate adventure where you command a customizable ship, recruit a loyal crew, and carve your legend across dangerous seas. Hunt treasure, battle rival captains, forge alliances, and decide whether you rule by fear or fame.', 'https://res.cloudinary.com/dxrtmaenj/image/upload/q_auto/f_auto/v1779360704/windward-legacy_yghezi.png', NULL, 10, true, NULL, 1);");
    await queryRunner.query("INSERT INTO public.games (id, created_at, updated_at, deleted_at, slug, title, short_description, description, cover_image_url, hero_image_url, sort_order, active, metadata, required_plan_id) VALUES (7, '2026-05-22 10:35:43.817098', '2026-05-22 10:35:43.817098', NULL, 'echoes-of-aurelia', 'Echoes Of Aurelia', 'A dark fantasy RPG of prophecy, dragons, and choices that decide a kingdom’s fate.', 'Epic dark fantasy RPG where two rival heirs are bound by a shattered prophecy. Explore a vast realm of ancient cities, forbidden magic, and dragon-haunted skies, shaping the fate of Aurelia through choice-driven quests and brutal combat.', 'https://res.cloudinary.com/dxrtmaenj/image/upload/q_auto/f_auto/v1779360704/echoes-of-aurelia_umyrhj.png', NULL, 10, true, NULL, 1);");
    await queryRunner.query("INSERT INTO public.games (id, created_at, updated_at, deleted_at, slug, title, short_description, description, cover_image_url, hero_image_url, sort_order, active, metadata, required_plan_id) VALUES (8, '2026-05-22 10:38:11.06638', '2026-05-22 10:38:11.06638', NULL, 'willowdale-academy', 'Willowdale Academy', 'A cozy pixel-art magic school sim full of friendship, spells, and discovery.', 'Charming pixel-art life sim where you enroll in a magical school nestled in a peaceful valley. Attend classes, brew potions, grow crops, decorate your dorm, befriend classmates, and uncover secrets hidden within the academy grounds.', 'https://res.cloudinary.com/dxrtmaenj/image/upload/q_auto/f_auto/v1779360704/willowdale-academy_lhxdkc.png', NULL, 20, true, NULL, 2);");
    await queryRunner.query("INSERT INTO public.games (id, created_at, updated_at, deleted_at, slug, title, short_description, description, cover_image_url, hero_image_url, sort_order, active, metadata, required_plan_id) VALUES (9, '2026-05-22 10:39:49.697142', '2026-05-22 10:39:49.697142', NULL, 'mighty-beavers', 'Mighty Beavers', 'A pixel-art beat ’em up starring martial arts beavers defending their dam.', 'Chaotic pixel-art beat ’em up where martial arts–trained beavers defend their dam from ruthless industrial wolves. Battle through forests, construction sites, and riverfront stages using combos, co-op moves, and over-the-top special attacks.', 'https://res.cloudinary.com/dxrtmaenj/image/upload/q_auto/f_auto/v1779288390/mighty-beavers_corhmh.png', NULL, 20, true, NULL, 2);");
    await queryRunner.query("INSERT INTO public.games (id, created_at, updated_at, deleted_at, slug, title, short_description, description, cover_image_url, hero_image_url, sort_order, active, metadata, required_plan_id) VALUES (10, '2026-05-22 10:45:20.401754', '2026-05-22 10:45:20.401754', NULL, 'secrets-of-rainy-weather', 'Secrets Of Rainy Weather', 'Two girls, one mystery. Unravel the shadows of Gray Truth.', 'Two schoolgirl detectives uncover dark secrets hidden within their academy''s walls. Investigate crime scenes, gather clues, and solve a chilling mystery that blurs the line between truth and deception in this gripping visual novel', 'https://res.cloudinary.com/dxrtmaenj/image/upload/q_auto/f_auto/v1779360704/secrets-of-rainy-weather_gk0hzd.png', NULL, 20, true, NULL, 2);");
    await queryRunner.query("INSERT INTO public.games (id, created_at, updated_at, deleted_at, slug, title, short_description, description, cover_image_url, hero_image_url, sort_order, active, metadata, required_plan_id) VALUES (11, '2026-05-22 10:47:17.179091', '2026-05-22 10:47:17.179091', NULL, 'iron-vale', 'Iron Vale', 'An epic open-world RPG of knights, dragons, and forgotten kingdoms.', 'Explore the vast open world of Iron Vale, a sprawling fantasy realm of floating citadels, ancient kingdoms, and dragon-filled skies. Forge your legend, battle mythical beasts, and uncover the secrets of a land on the brink of war.', 'https://res.cloudinary.com/dxrtmaenj/image/upload/q_auto/f_auto/v1779288539/iron-vale_b6dshv.png', NULL, 20, true, NULL, 2);");
    await queryRunner.query("INSERT INTO public.games (id, created_at, updated_at, deleted_at, slug, title, short_description, description, cover_image_url, hero_image_url, sort_order, active, metadata, required_plan_id) VALUES (12, '2026-05-22 10:49:02.468808', '2026-05-22 10:49:02.468808', NULL, 'elemental-legacy', 'Elemental Legacy', 'Harness the five elements and shape the fate of a fractured world.', 'Master the powers of fire, water, earth, air, and lightning in Elemental Legacy. Choose your path, unleash devastating combos, and join legendary benders in an epic battle to restore balance to a world torn by elemental chaos.', 'https://res.cloudinary.com/dxrtmaenj/image/upload/q_auto/f_auto/v1779288332/elemental-legacy_imsv66.png', NULL, 20, true, NULL, 2);");
    await queryRunner.query("INSERT INTO public.games (id, created_at, updated_at, deleted_at, slug, title, short_description, description, cover_image_url, hero_image_url, sort_order, active, metadata, required_plan_id) VALUES (13, '2026-05-22 10:57:35.292212', '2026-05-22 10:57:35.292212', NULL, 'ninja-master', 'Ninja Master', 'Walk the path of the sword in a feudal Japan torn by war and shadow.', 'Step into a war-torn feudal Japan where shinobi and samurai clash beneath blood-red moons. Master the blade, embrace the shadows, and choose your path of honor or vengeance in a brutal action epic of steel and sacrifice.', 'https://res.cloudinary.com/dxrtmaenj/image/upload/q_auto/f_auto/v1779288331/ninja_pgxpwi.png', NULL, 30, true, NULL, 3);");
    await queryRunner.query("INSERT INTO public.games (id, created_at, updated_at, deleted_at, slug, title, short_description, description, cover_image_url, hero_image_url, sort_order, active, metadata, required_plan_id) VALUES (14, '2026-05-22 10:59:17.688381', '2026-05-22 10:59:17.688381', NULL, 'shadow-covenant', 'Shadow Covenant', 'A high-stakes spy thriller where every shadow hides a secret.', 'Dive into a world of espionage, betrayal, and global conspiracy. As an elite agent of Shadow Covenant, infiltrate criminal empires, outsmart rival spies, and uncover a plot that could reshape the world order. Trust no one.', 'https://res.cloudinary.com/dxrtmaenj/image/upload/q_auto/f_auto/v1779288332/shadow-covenant_qmjtgm.png', NULL, 30, true, NULL, 3);");
