    await queryRunner.query("INSERT INTO public.games (id, created_at, updated_at, deleted_at, slug, title, short_description, description, cover_image_url, hero_image_url, sort_order, active, metadata, required_plan_id) VALUES (16, '2026-05-22 11:06:03.551962', '2026-05-22 11:06:03.551962', NULL, 'lost-adventure', 'Lost Adventure', 'Uncover the secrets of a lost civilization in an epic action-adventure.', 'Embark on a thrilling journey as an explorer overlooking a breathtaking, forgotten valley. Discover ancient stone temples, hidden waterfalls, and mystical ruins nestled among towering mountains in a world full of secrets.', 'https://res.cloudinary.com/dxrtmaenj/image/upload/q_auto/f_auto/v1779288390/lost-adventure_jjvouz.png', NULL, 30, true, NULL, 3);");
    await queryRunner.query("INSERT INTO public.games (id, created_at, updated_at, deleted_at, slug, title, short_description, description, cover_image_url, hero_image_url, sort_order, active, metadata, required_plan_id) VALUES (17, '2026-05-22 11:08:36.602039', '2026-05-22 11:08:36.602039', NULL, 'night-race', 'Night Race', 'Tear through vibrant neon streets in adrenaline-fueled illegal night races.', 'Experience high-octane illegal street racing through neon-lit metropolis streets at night. Speed through rain-slicked asphalt, dodge traffic, and dominate the underground scene in highly customized sports cars.', 'https://res.cloudinary.com/dxrtmaenj/image/upload/q_auto/f_auto/v1779288396/night-race_g0afui.png', NULL, 30, true, NULL, 3);");
    await queryRunner.query("INSERT INTO public.games (id, created_at, updated_at, deleted_at, slug, title, short_description, description, cover_image_url, hero_image_url, sort_order, active, metadata, required_plan_id) VALUES (18, '2026-05-22 11:09:55.040419', '2026-05-22 11:09:55.040419', NULL, 'deep-sector', 'Deep Sector', 'Survive a terrifying alien predator in a dark, abandoned deep-space station.', 'Survive the ultimate sci-fi nightmare inside a ruined, blood-splattered space station. Armed only with a flashlight, navigate dark, claustrophobic corridors while a terrifying, monstrous alien predator stalks you from the shadows.', 'https://res.cloudinary.com/dxrtmaenj/image/upload/q_auto/f_auto/v1779288444/deep-sector_i46iin.png', NULL, 30, true, NULL, 3);");
